pm.sendRequest({
    url: pm.variables.get("baseUrl") + "/api/v1/sql/select",
    method: "POST",
    header: {
        "Content-Type": "application/json",
        "x-api-key": pm.variables.get("apiKey")
    },
    body: {
        mode: "raw",
        raw: JSON.stringify({
            sql: "SELECT id, nombre, email, activo FROM usuarios WHERE activo = false ORDER BY id LIMIT 1",
            params: []
        })
    }
}, function (err, res) {
    if (err) {
        console.log("Error consultando BD:", err);
        return;
    }

    const json = res.json();
    console.log("Respuesta SQL:", json);

    const filas = json.data || [];

    if (filas.length === 0) {
        throw new Error("No se encontró ningún usuario activo en la BD");
    }

    const usuario = filas[0];

    pm.environment.set("emailBD", usuario.email);
    pm.environment.set("usuarioIdBD", usuario.id);

    console.log("Usuario obtenido desde BD:", usuario.id, usuario.email);
});

pm.test("Usuario inactivo rechazado con status 400", function () {
    pm.response.to.have.status(400);
});

pm.test("La respuesta es JSON", function () {
    pm.response.to.be.json;
});

pm.test("El error corresponde a VALIDATION_ERROR", function () {
    const json = pm.response.json();

    pm.expect(json).to.have.property("error");
    pm.expect(json.error).to.have.property("code");
    pm.expect(json.error.code).to.eql("VALIDATION_ERROR");
});

pm.test("Se utilizó un usuario obtenido dinámicamente desde BD", function () {
    const emailBD = pm.environment.get("emailBD");
    const usuarioIdBD = pm.environment.get("usuarioIdBD");

    pm.expect(emailBD).to.be.a("string").and.not.empty;
    pm.expect(usuarioIdBD).to.exist;
});

console.log("Email inactivo obtenido desde BD:", pm.environment.get("emailBD"));
